const input = $json.body ?? $json;
const errors = [];
const outcomes = ['callback_requested', 'delivery_unresolved', 'category_interested', 'demand_reduced', 'no_response', 'order_received'];
const isDate = (v) => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) && !Number.isNaN(Date.parse(v + 'T00:00:00Z'));
const isDateOrDateTime = (v) => typeof v === 'string' && !Number.isNaN(Date.parse(v));
for (const key of ['eventId', 'accountId']) if (typeof input[key] !== 'string' || !input[key].trim()) errors.push({ field: key, message: `${key} is required and must be a non-empty string` });
if (input.approved !== true) errors.push({ field: 'approved', message: 'approved must be exactly true' });
if (input.mode !== 'simulation') errors.push({ field: 'mode', message: 'mode must be simulation' });
if (!isDate(input.contactDate)) errors.push({ field: 'contactDate', message: 'contactDate is required in YYYY-MM-DD format' });
if (!outcomes.includes(input.outcome)) errors.push({ field: 'outcome', message: 'Unsupported outcome', allowedValues: outcomes });
if (input.outcome === 'callback_requested' && !isDateOrDateTime(input.callbackAt)) errors.push({ field: 'callbackAt', message: 'callbackAt is required as an ISO date or datetime for callback_requested' });
if (input.callbackAt !== undefined && input.callbackAt !== null && !isDateOrDateTime(input.callbackAt)) errors.push({ field: 'callbackAt', message: 'callbackAt must be an ISO date or datetime when supplied' });
if (input.representativeNotes !== undefined && input.representativeNotes !== null && typeof input.representativeNotes !== 'string') errors.push({ field: 'representativeNotes', message: 'representativeNotes must be a string, null, or omitted' });
if (input.outcome === 'order_received') {
  const m = input.monitoring;
  const validDate = m && Object.keys(m).length === 1 && isDate(m.date);
  const validInterval = m && Object.keys(m).length === 1 && Number.isInteger(m.intervalDays) && m.intervalDays > 0;
  if (!validDate && !validInterval) errors.push({ field: 'monitoring', message: 'order_received requires monitoring with exactly one of date (YYYY-MM-DD) or intervalDays (positive integer)' });
}
if (isDate(input.contactDate) && input.outcome === 'callback_requested' && isDateOrDateTime(input.callbackAt) && Date.parse(input.callbackAt) < Date.parse(input.contactDate + 'T00:00:00Z')) errors.push({ field: 'callbackAt', message: 'callbackAt cannot be before contactDate' });
if (errors.length) {
  const approvalOnly = errors.length === 1 && errors[0].field === 'approved';
  return [{ json: { ok: false, httpCode: approvalOnly ? 403 : 400, body: { error: { code: approvalOnly ? 'APPROVAL_REQUIRED' : 'INVALID_REQUEST', message: approvalOnly ? 'The outcome was not approved' : 'Record Outcome request failed validation', details: errors } } } }];
}
return [{ json: { ok: true, request: { ...input, eventId: input.eventId.trim(), accountId: input.accountId.trim() } } }];

if (!$json.ok) return [{ json: $json }];
const request = $json.request;
const CONFIG = {
  calendarConvention: 'calendar_days_utc',
  timingDays: {
    delivery_unresolved: 0,
    category_interested: 2,
    demand_reduced: 30,
    no_response: 3
  }
};
const routes = {
  callback_requested: { status: 'callback_scheduled', taskType: 'callback', purpose: 'retention_callback' },
  delivery_unresolved: { status: 'service_escalation_required', taskType: 'service_escalation', purpose: 'service_issue_resolution' },
  category_interested: { status: 'proposal_preparation_required', taskType: 'category_proposal', purpose: 'category_proposal' },
  demand_reduced: { status: 'account_review_scheduled', taskType: 'account_review', purpose: 'demand_review' },
  no_response: { status: 'follow_up_scheduled', taskType: 'follow_up_attempt', purpose: 'retention_contact_reminder' },
  order_received: { status: 'monitoring_scheduled', taskType: 'recovery_monitoring', purpose: 'retention_monitoring' }
};
return [{ json: { ...$json, config: CONFIG, route: routes[request.outcome] } }];

if (!$json.ok) return [{ json: $json }];
const { request: r, route, config } = $json;
const addDays = (date, days) => { const d = new Date(date + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + days); return d.toISOString().slice(0, 10); };
const fnv1a = (text) => { let h = 0x811c9dc5; for (let i = 0; i < text.length; i++) { h ^= text.charCodeAt(i); h = Math.imul(h, 0x01000193); } return (h >>> 0).toString(16).padStart(8, '0'); };
const taskId = `task_${route.taskType}_${fnv1a(`${r.eventId}|${route.taskType}`)}`;
let dueAt;
if (r.outcome === 'callback_requested') dueAt = r.callbackAt;
else if (r.outcome === 'order_received') dueAt = r.monitoring.date ?? addDays(r.contactDate, r.monitoring.intervalDays);
else dueAt = addDays(r.contactDate, config.timingDays[r.outcome]);
const instructions = {
  upsert: [{
    taskId,
    accountId: r.accountId,
    type: route.taskType,
    purpose: route.purpose,
    dueAt,
    status: 'open',
    sourceEventId: r.eventId,
    notes: r.representativeNotes ?? null
  }],
  cancel: []
};
const messages = {
  callback_requested: 'Contact the account at the requested callback time.',
  delivery_unresolved: 'Escalate the unresolved delivery issue to the service team for investigation.',
  category_interested: 'Prepare a category proposal for representative review; do not send automatically.',
  demand_reduced: 'Review the account later using updated evidence; reduced demand is not necessarily churn.',
  no_response: 'Make one follow-up contact attempt on the configured date.',
  order_received: 'Monitor the account on the requested date. This order is not proof of sustained recovery.'
};
if (r.outcome === 'order_received') {
  instructions.cancel.push({
    accountId: r.accountId,
    purpose: 'retention_contact_reminder',
    scope: 'open_tasks_only',
    excludePurposes: ['service_issue_resolution'],
    reason: 'order_received'
  });
}
instructions.upsert[0].instruction = messages[r.outcome];
return [{ json: { ok: true, httpCode: 200, body: {
  eventId: r.eventId,
  accountId: r.accountId,
  outcome: r.outcome,
  actionStatus: route.status,
  calendarConvention: config.calendarConvention,
  taskInstructions: instructions
} } }];
